toolScript:
let hintInterval = null;
// --- GAME STATE & GAMIFICATION ---
        const RANKS = ["NOVICE", "INITIATE", "TECH-ADEPT", "CYBER-MONK", "FLOW-MASTER", "NEURO-GOD"];
        let pilotData = {
            xp: 0,
            level: 0,
            streak: 0,
            lastLogin: null,
            tutorialDone: false
        };
        function loadPilotData() {
            const saved = localStorage.getItem('flow_pilot_data_v2');
            if (saved) {
                try {
                    pilotData = JSON.parse(saved);
                } catch (e) {
                    pilotData = { xp: 0, level: 0, streak: 1, lastLogin: null, tutorialDone: false };
                }
                const today = new Date().toDateString();
                if (pilotData.lastLogin !== today) {
                    pilotData.lastLogin = today;
                    pilotData.streak = (pilotData.streak || 0) + 1;
                    savePilotData();
                }
            } else {
                pilotData.lastLogin = new Date().toDateString();
                pilotData.streak = 1;
                pilotData.tutorialDone = false;
                savePilotData();
                setTimeout(startTutorial, 1000);
            }
            updateHUD();
        }
        function savePilotData() {
            try {
                localStorage.setItem('flow_pilot_data_v2', JSON.stringify(pilotData));
            } catch (e) {}
            updateHUD();
        }
        function addXP(amount, sourceElementId) {
            pilotData.xp += amount;
            const newLevel = Math.floor(pilotData.xp / 500);
            if (newLevel > pilotData.level) {
                pilotData.level = newLevel;
                showHint(`LEVEL UP! RANK PROMOTED: ${RANKS[Math.min(pilotData.level, RANKS.length - 1)]}`);
            }
            savePilotData();
            showFloatingText(amount, sourceElementId);
        }
        function updateHUD() {
            const currentRank = RANKS[Math.min(pilotData.level, RANKS.length - 1)];
            const xpForNext = (pilotData.level + 1) * 500;
            const currentLevelXP = pilotData.xp - (pilotData.level * 500);
            const percentage = Math.min((currentLevelXP / 500) * 100, 100);
            const rankEl = document.getElementById('pilot-rank');
            const xpEl = document.getElementById('pilot-xp');
            const barEl = document.getElementById('xp-bar');
            const streakEl = document.getElementById('streak-count');
            if (rankEl) rankEl.innerText = `RANK: ${currentRank}`;
            if (xpEl) xpEl.innerText = `${Math.floor(pilotData.xp)} XP`;
            if (barEl) barEl.style.width = `${percentage}%`;
            if (streakEl) streakEl.innerText = pilotData.streak || 1;
        }
        function showFloatingText(amount, elementId) {
            const el = document.getElementById(elementId);
            if (!el) return;
            const rect = el.getBoundingClientRect();
            const floater = document.createElement('div');
            floater.className = 'xp-float';
            floater.innerText = `+${amount} XP`;
            floater.style.left = `${rect.left + rect.width / 2}px`;
            floater.style.top = `${rect.top}px`;
            document.body.appendChild(floater);
            setTimeout(() => floater.remove(), 1500);
        }
        // --- HINT SYSTEM ---
        const HINTS = [
            "Hydrate: Even 2% water loss drops focus by 20%.",
            "Box Breathing: Inhale 4s, Hold 4s, Exhale 4s.",
            "Visual Noise: Hide your bookmarks bar for clarity.",
            "Posture Check: Unclench your jaw. Drop your shoulders.",
            "The 20-20-20 Rule: Look 20ft away for 20s every 20m.",
            "Dopamine Detox: Boredom is the precursor to creativity."
        ];
        function cycleHints() {
            const hintEl = document.getElementById('hint-text');
            if (!hintEl) return;
            let idx = 0;
            hintInterval = setInterval(() => {
                hintEl.style.opacity = '0';
                setTimeout(() => {
                    idx = (idx + 1) % HINTS.length;
                    hintEl.innerText = HINTS[idx];
                    hintEl.style.opacity = '1';
                }, 500);
            }, 10000);
        }
        function showHint(msg) {
            const hintEl = document.getElementById('hint-text');
            if (!hintEl) return;
            hintEl.innerText = msg;
            if (hintEl.parentElement) {
                hintEl.parentElement.classList.add('bg-fuchsia-900/40');
                setTimeout(() => hintEl.parentElement.classList.remove('bg-fuchsia-900/40'), 3000);
            }
        }
        // --- TUTORIAL / ONBOARDING ---
        let tutStep = 0;
        const tutorialSteps = [
            { id: 'module-timer', title: 'CHRONOMETER', text: 'Step 1: Set your focus duration. The 25-minute Pomodoro is standard, but you can adjust modes below.' },
            { id: 'module-audio', title: 'AUDIO ENGINE', text: 'Step 2: Engage Brown Noise. It masks external distractions and soothes the ADHD brain.' },
            { id: 'module-tasks', title: 'MISSION LOG', text: 'Step 3: Define directives. Checking off tasks grants XP and dopamine hits.' },
            { id: 'pilot-rank', title: 'PILOT STATS', text: 'Track your progress, earn Ranks, and build your Daily Streak.' }
        ];
        function startTutorial() {
            if (pilotData.tutorialDone) return;
            const overlay = document.getElementById('tutorial-overlay');
            if (overlay) overlay.style.display = 'flex';
            showTutorialStep(0);
        }
        function showTutorialStep(index) {
            document.querySelectorAll('.tutorial-highlight').forEach(el => el.classList.remove('tutorial-highlight'));
            if (index >= tutorialSteps.length) {
                endTutorial();
                return;
            }
            const step = tutorialSteps[index];
            const target = document.getElementById(step.id);
            if (target) target.classList.add('tutorial-highlight');
            if (step.id === 'pilot-rank') {
                const hud = document.querySelector('.hud-panel');
                if (hud) hud.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }
            const titleEl = document.getElementById('tut-title');
            const descEl = document.getElementById('tut-desc');
            const nextBtn = document.getElementById('tut-next-btn');
            if (titleEl) titleEl.innerText = step.title;
            if (descEl) descEl.innerText = step.text;
            if (nextBtn) nextBtn.innerText = (index === tutorialSteps.length - 1) ? "FINISH" : "NEXT STEP";
            tutStep = index;
        }
        function nextTutorialStep() {
            showTutorialStep(tutStep + 1);
        }
        function skipTutorial() {
            endTutorial();
        }
        function endTutorial() {
            const overlay = document.getElementById('tutorial-overlay');
            if (overlay) overlay.style.display = 'none';
            document.querySelectorAll('.tutorial-highlight').forEach(el => el.classList.remove('tutorial-highlight'));
            pilotData.tutorialDone = true;
            savePilotData();
            showHint("System Online. Good luck, Pilot.");
        }
        // --- CHIME SYNTHESIZER (Self-Contained Offline Web Audio) ---
        function playChime() {
            try {
                const AudioCtxClass = window.AudioContext || window.webkitAudioContext;
                if (!AudioCtxClass) return;
                const ctx = audioCtx || new AudioCtxClass();
                if (ctx.state === 'suspended') {
                    ctx.resume().catch(() => {});
                }
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = 'sine';
                const now = ctx.currentTime;
                osc.frequency.setValueAtTime(587.33, now);
                osc.frequency.exponentialRampToValueAtTime(880, now + 0.15);
                osc.frequency.exponentialRampToValueAtTime(1174.66, now + 0.3);
                gain.gain.setValueAtTime(0.2, now);
                gain.gain.exponentialRampToValueAtTime(0.001, now + 0.85);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(now);
                osc.stop(now + 0.85);
            } catch (e) {
                console.warn('Audio chime unavailable', e);
            }
        }
        // --- POMODORO LOGIC ---
        let timeLeft = 25 * 60;
        let timerId = null;
        let isWork = true;
        function updateDisplay() {
            const m = Math.floor(timeLeft / 60).toString().padStart(2, '0');
            const s = (timeLeft % 60).toString().padStart(2, '0');
            const disp = document.getElementById('timer-display');
            if (disp) disp.innerText = `${m}:${s}`;
            document.title = `${m}:${s} - Deep Work`;
        }
        function toggleTimer() {
            const btn = document.getElementById('start-btn');
            if (timerId) {
                clearInterval(timerId);
                timerId = null;
                if (btn) {
                    btn.innerText = "RESUME";
                    btn.classList.replace('bg-red-500', 'bg-cyan-600');
                }
            } else {
                if (!hintInterval) cycleHints();
                timerId = setInterval(() => {
                    if (timeLeft > 0) {
                        timeLeft--;
                        updateDisplay();
                    } else {
                        clearInterval(timerId);
                        timerId = null;
                        if (isWork) {
                            addXP(100, 'timer-display');
                            playChime();
                            showHint("SESSION COMPLETE. +100 XP. TAKE A REST.");
                        }
                        if (btn) btn.innerText = "START";
                    }
                }, 1000);
                if (btn) {
                    btn.innerText = "PAUSE";
                    btn.classList.replace('bg-cyan-600', 'bg-red-500');
                }
            }
        }
        function resetTimer() {
            if (timerId) clearInterval(timerId);
            timerId = null;
            timeLeft = 25 * 60;
            isWork = true;
            updateDisplay();
            const btn = document.getElementById('start-btn');
            if (btn) {
                btn.innerText = "INITIALIZE";
                btn.className = "bg-cyan-600 hover:bg-cyan-500 text-black font-bold py-2 px-6 rounded-sm uppercase text-xs tracking-wider transition shadow-[0_0_10px_rgba(6,182,212,0.3)]";
            }
        }
        function setMode(minutes) {
            if (timerId) clearInterval(timerId);
            timerId = null;
            timeLeft = minutes * 60;
            updateDisplay();
            const btn = document.getElementById('start-btn');
            if (btn) btn.innerText = "START";
            isWork = (minutes === 25 || minutes === 90);
        }
        // --- BROWN NOISE GENERATOR (Web Audio API) ---
        let audioCtx = null, brownNoiseNode = null, gainNode = null;
        let isPlaying = false;
        function toggleAudio() {
            const btn = document.getElementById('audio-btn');
            const btnText = document.getElementById('audio-btn-text');
            const status = document.getElementById('audio-status');
            if (isPlaying) {
                if (gainNode) {
                    try { gainNode.disconnect(); } catch (e) {}
                }
                if (audioCtx && audioCtx.state === 'running') {
                    try { audioCtx.suspend(); } catch (e) {}
                }
                isPlaying = false;
                if (btnText) btnText.innerText = "Connect Audio";
                if (btn) {
                    btn.classList.remove('bg-fuchsia-900/50', 'border-fuchsia-400');
                    btn.classList.add('border-fuchsia-600');
                }
                if (status) {
                    status.classList.remove('status-active');
                    status.classList.add('bg-slate-700');
                }
            } else {
                if (!audioCtx) initAudio();
                if (audioCtx) {
                    audioCtx.resume().then(() => {
                        if (gainNode) gainNode.connect(audioCtx.destination);
                        isPlaying = true;
                        if (btnText) btnText.innerText = "Disconnect Link";
                        if (btn) {
                            btn.classList.add('bg-fuchsia-900/50', 'border-fuchsia-400');
                        }
                        if (status) {
                            status.classList.remove('bg-slate-700');
                            status.classList.add('status-active');
                        }
                    }).catch(err => console.warn('Audio resume error', err));
                }
            }
        }
        function initAudio() {
            if (audioCtx) return;
            const AudioCtxClass = window.AudioContext || window.webkitAudioContext;
            if (!AudioCtxClass) return;
            audioCtx = new AudioCtxClass();
            const bufferSize = 4096;
            brownNoiseNode = audioCtx.createScriptProcessor(bufferSize, 1, 1);
            let lastOut = 0;
            brownNoiseNode.onaudioprocess = function (e) {
                const output = e.outputBuffer.getChannelData(0);
                for (let i = 0; i < bufferSize; i++) {
                    const white = Math.random() * 2 - 1;
                    output[i] = (lastOut + (0.02 * white)) / 1.02;
                    lastOut = output[i];
                    output[i] *= 3.5;
                }
            };
            gainNode = audioCtx.createGain();
            const slider = document.getElementById('volume-slider');
            const initialGain = slider ? parseFloat(slider.value) : 0.5;
            gainNode.gain.setValueAtTime(initialGain, audioCtx.currentTime);
            brownNoiseNode.connect(gainNode);

            if (slider) {
                slider.addEventListener('input', (e) => {
                    if (gainNode && audioCtx) {
                        gainNode.gain.setValueAtTime(parseFloat(e.target.value), audioCtx.currentTime);
                    }
                });
            }
        }
        // --- TASKS LOGIC (Persistent Local Storage) ---
        let quests = [];
        function escapeHtml(str) {
            return String(str).replace(/[&<>"']/g, s => ({
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#39;'
            })[s]);
        }
        function loadQuests() {
            try {
                const saved = localStorage.getItem('flow_pilot_tasks_v2');
                if (saved) {
                    quests = JSON.parse(saved);
                } else {
                    quests = [
                        { id: 'task-1', text: 'Calibrate environment: Eliminate visual clutter', completed: false },
                        { id: 'task-2', text: 'Engage 25m Deep Work Pomodoro block', completed: false }
                    ];
                }
            } catch (e) {
                quests = [];
            }
            renderQuests();
        }
        function saveQuests() {
            try {
                localStorage.setItem('flow_pilot_tasks_v2', JSON.stringify(quests));
            } catch (e) {}
        }
        function renderQuests() {
            const list = document.getElementById('task-list');
            if (!list) return;
            list.innerHTML = '';
            quests.forEach(q => {
                const li = document.createElement('li');
                li.id = q.id;
                li.className = `flex justify-between items-center group cursor-pointer hover:bg-emerald-900/20 p-2 rounded transition-colors border-b border-emerald-900/30 ${q.completed ? 'bg-emerald-900/10' : ''}`;
                li.innerHTML = `
                    <span class="flex items-center gap-2">
                        <span class="w-4 h-4 border border-emerald-500/50 rounded-sm flex-shrink-0 flex items-center justify-center text-emerald-500 transition-opacity check-icon ${q.completed ? '' : 'opacity-0'}"><svg class="w-4 h-4 inline-block text-emerald-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg></span>
                        <span class="task-text transition-all ${q.completed ? 'line-through text-emerald-700 opacity-50' : ''}">${escapeHtml(q.text)}</span>
                    </span>
                    <button type="button" aria-label="Remove Task" onclick="removeQuest('${q.id}', event)" class="text-emerald-700 hover:text-emerald-400 opacity-0 group-hover:opacity-100 px-2 text-xl">&times;</button>
                `;
                li.onclick = function (e) {
                    if (e.target.tagName !== 'BUTTON') {
                        toggleQuest(q.id);
                    }
                };
                list.appendChild(li);
            });
        }
        function addQuest() {
            const input = document.getElementById('task-input');
            if (!input) return;
            const text = input.value.trim();
            if (!text) return;
            const newQuest = {
                id: 'task-' + Date.now(),
                text: text,
                completed: false
            };
            quests.unshift(newQuest);
            saveQuests();
            renderQuests();
            input.value = '';
        }
        function toggleQuest(id) {
            const q = quests.find(item => item.id === id);
            if (!q) return;
            q.completed = !q.completed;
            saveQuests();
            renderQuests();
            if (q.completed) {
                addXP(50, id);
            }
        }
        function removeQuest(id, event) {
            if (event) event.stopPropagation();
            quests = quests.filter(item => item.id !== id);
            saveQuests();
            renderQuests();
        }
        document.getElementById('task-input')?.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') addQuest();
        });
        // --- UTILS ---
        function toggleFullscreen() {
            const elem = document.getElementById('command-center');
            if (!elem) return;
            if (!document.fullscreenElement) {
                elem.requestFullscreen().catch(err => {
                    alert(`Error attempting to enable full-screen mode: ${err.message} (${err.name})`);
                });
            } else {
                document.exitFullscreen();
            }
        }
        // Init
        window.addEventListener('load', () => {
            loadPilotData();
            loadQuests();
            const hintEl = document.getElementById('hint-text'); if (hintEl) hintEl.innerText = HINTS[0];
        });
